FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE avg(body_mass_g) AS avg_body_mass_g GROUP BY island, species |> AGGREGATE bar(x => species, y => scaled(avg_body_mass_g, title => 'avg(body_mass_g)')) AS chart_bar GROUP BY island |> AS charts |> LEFT OUTER JOIN (FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE avg(body_mass_g) AS avg_body_mass_g GROUP BY island |> AGGREGATE rule(y => scaled(avg_body_mass_g, title => 'avg(body_mass_g)')) AS chart_rule GROUP BY island) AS charts_2 ON charts.island IS NOT DISTINCT FROM charts_2.island |> SELECT charts.island, layer(charts.chart_bar, charts_2.chart_rule) AS chart |> ORDER BY island
